  const list=document.getElementById('seedList');list.innerHTML='';crops.filter(c=>state.seeds[c.id]>0).forEach(c=>{const btn=document.createElement('button');btn.className='seed-item '+(state.selected===c.id?'active':'');btn.innerHTML=`<span class="seed-emoji">${c.emoji}</span><span class="seed-meta"><strong>${c.name}</strong><span>Crece en ${c.time}s · vale ${c.value} 🪙</span></span><span class="seed-count">×${state.seeds[c.id]}</span>`;btn.addEventListener('click',()=>{state.selected=c.id;save();render()});list.append(btn)});
