  const qlist=document.getElementById('questList');qlist.innerHTML='';quests.forEach(q=>{const value=q.id==='plant'?state.planted:q.id==='harvest'?state.harvested:state.varieties.length,done=state.claimed.includes(q.id),amount=Math.min(value,q.target),row=document.createElement('div');row.className='quest';row.innerHTML=`<div class="quest-icon">${q.icon}</div><div class="quest-text"><strong>${q.title}</strong><span>${done?'¡Encargo completado!':q.detail}</span></div><div class="quest-progress ${done?'done':''}">${done?'✓':`${amount}/${q.target}`}</div><div class="quest-bar"><i style="width:${Math.round(amount/q.target*100)}%"></i></div>`;row.addEventListener('click',()=>{if(!done&&value>=q.target){state.claimed.push(q.id);state.coins+=q.reward;save();render();toast(`¡Encargo cumplido! +${q.reward} monedas 🪙`)}});if(!done&&value>=q.target){row.style.cursor='pointer';row.title=`Toca para reclamar ${q.reward} monedas`}qlist.append(row)});
  const exp=document.getElementById('expandButton');const cost=state.unlocked===6?80:state.unlocked===9?130:0;exp.textContent=state.unlocked>=12?'✨ Jardín completo':`＋ Ampliar jardín · ${cost} 🪙`;exp.disabled=state.unlocked>=12||state.coins<cost;

