+function onPlot(i,event){if(i>=state.unlocked){toast('Amplía tu jardín para desbloquear este bancal 🌿');return}const p=state.plots[i];if(!p){if(!state.selected||!state.seeds[state.selected]){toast('¡Visita el mercado para conseguir semillas!');return}const crop=crops.find(c=>c.id===state.selected);state.seeds[crop.id]--;state.plots[i]={crop:crop.id,readyAt:Date.now()+crop.time*1000};state.planted++;if(!state.varieties.includes(crop.id))state.varieties.push(crop.id);state.selected=state.seeds[crop.id]>0?crop.id:crops.find(c=>state.seeds[c.id]>0)?.id||null;popEmoji('🌱',event);render();toast(`${crop.emoji} ¡${crop.name} plantada con cariño!`)}else if(timeLeft(p)===0){const crop=crops.find(c=>c.id===p.crop)||crops[0];state.coins+=crop.value;state.harvested++;state.plots[i]=null;popEmoji('✨',event);render();toast(`${crop.emoji} ¡${crop.name} cosechada! +${crop.value} monedas`)}else toast('¡Está creciendo! Vuelve en un ratito 🌱')}
 function popEmoji(text,e){if(!e)return;const x=document.createElement('span');x.className='float';x.textContent=text;x.style.left=e.clientX+'px';x.style.top=e.clientY+'px';document.body.append(x);setTimeout(()=>x.remove(),950)}
 document.getElementById('expandButton').addEventListener('click',()=>{const cost=state.unlocked===6?80:state.unlocked===9?130:0;if(state.unlocked<12&&state.coins>=cost){state.coins-=cost;state.unlocked=Math.min(12,state.unlocked+3);save();render();toast('¡Tu jardín creció! Hay nuevos bancales 🌼')}});
 const modal=document.getElementById('marketModal');function openMarket(){const grid=document.getElementById('marketGrid');grid.innerHTML='';crops.forEach((c,i)=>{const card=document.createElement('div');card.className='market-card';const locked=i>1&&!state.seeds[c.id];card.innerHTML=`<div class="market-card-top"><span>${c.emoji}</span><strong>${c.name}</strong></div><p>${c.desc}<br>Crece en ${c.time}s · cosecha ${c.value} 🪙</p><button class="buy-button" ${state.coins<c.cost?'disabled':''}>Comprar semilla · ${c.cost} 🪙</button>`;card.querySelector('button').addEventListener('click',()=>{if(state.coins<c.cost){toast('Te faltan monedas para esa semilla.');return}state.coins-=c.cost;state.seeds[c.id]=(state.seeds[c.id]||0)+1;state.selected=c.id;save();render();openMarket();toast(`${c.emoji} ¡Semilla de ${c.name} añadida!`)});grid.append(card)});modal.classList.add('open')}
 document.getElementById('marketOpen').addEventListener('click',openMarket);document.getElementById('marketClose').addEventListener('click',()=>modal.classList.remove('open'));modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')modal.classList.remove('open')});

